    var hist = _tcJson(TC_PFX + "_tc_shown", []);
    if (!Array.isArray(hist)) hist = [];
    if (hist[0] !== sig) { hist.unshift(sig); _tcSet(TC_PFX + "_tc_shown", JSON.stringify(hist.slice(0, 4))); }
