    var values = ["__all__", "__old__"];
    var total = 0;
    idx.forEach(function (x) {
      var dt = new Date(x.ts || 0);
      entries.push((x.n || "이름 없음") + " · " + (x.d < x.u ? "일부 " + x.d + "/" + x.u + "문장" : x.u + "문장") + " · " + _tcFmtSize(x.s || 0) + " · " + (dt.getMonth() + 1) + "/" + dt.getDate());
      values.push(x.h);
      total += x.s || 0;
    });
